_EXPECTED_LOCALES = {code for code, _label in LANGUAGE_OPTIONS if code != "en"}
if set(_CONTROL_ROWS) != _EXPECTED_LOCALES:
    raise ValueError(
        "Help-hub control catalogs must cover every non-English locale"
    )
if len(HELP_HUB_CONTROL_KEYS) != 40 or len(set(HELP_HUB_CONTROL_KEYS)) != 40:
    raise ValueError("Help-hub control sources must be exactly 40 unique keys")

HELP_HUB_CONTROL_CATALOGS: dict[str, dict[str, str]] = {
    locale: dict(zip(HELP_HUB_CONTROL_KEYS, row.split("|"), strict=True))
    for locale, row in _CONTROL_ROWS.items()
}

for _locale, _entries in HELP_HUB_CONTROL_CATALOGS.items():
    for _source, _translation in _entries.items():
        if not _translation.strip() or _translation == _source:
            raise ValueError(
                f"Missing help-hub control translation: {_locale}: {_source}"
            )

_CONTROL_GROUPS = (
    (HELP_HUB_FORM_KEYS, HELP_HUB_FORM_CATALOGS),
    (HELP_HUB_CALENDAR_KEYS, HELP_HUB_CALENDAR_CATALOGS),
    (HELP_HUB_COPY_KEYS, HELP_HUB_COPY_CATALOGS),
    (HELP_HUB_FIELD_KEYS, HELP_HUB_FIELD_CATALOGS),
)
_ALL_CONTROL_KEYS = tuple(
    dict.fromkeys(
        (
            *HELP_HUB_CONTROL_KEYS,
            *(source for keys, _catalogs in _CONTROL_GROUPS for source in keys),
        )
    )
)
HELP_HUB_CONTROL_KEYS = _ALL_CONTROL_KEYS
for _locale in _EXPECTED_LOCALES:
    for _keys, _catalogs in _CONTROL_GROUPS:
        if set(_catalogs) != _EXPECTED_LOCALES:
            raise ValueError(
                "Help-hub control catalog locale coverage is incomplete"
            )
        if set(_catalogs[_locale]) != set(_keys):
            raise ValueError(
                f"Help-hub control source coverage is incomplete: {_locale}"
            )
        HELP_HUB_CONTROL_CATALOGS[_locale].update(_catalogs[_locale])
    if set(HELP_HUB_CONTROL_CATALOGS[_locale]) != set(HELP_HUB_CONTROL_KEYS):
        raise ValueError(
            f"Help-hub control merged source coverage is incomplete: {_locale}"
        )
